245	    protected void onNewIntent(Intent intent) {
246	        super.onNewIntent(intent);
247	
248	        if (intent.getDataString() != null) {
249	            if (!intent.getDataString().isEmpty()) {
250	                File iFile;
251	                try {
252	                    iFile = new File(Uri.decode(intent.getDataString().split("://")[1]));
253	                } catch (IndexOutOfBoundsException e) {
254	                    iFile = new File(Uri.decode(intent.getDataString()));
255	                }
256	                if (iFile.exists()) {
257	                    FMFile file = new FMFile(iFile);
258	                    ArchiveParentFinder parentFinder = new ArchiveParentFinder(file.getFile().getAbsolutePath()).invoke();
259	                    FMArchive archiveToExtract = null;
260	                    if(!file.isArchive() && parentFinder.isArchive()) {
261	                        archiveToExtract = parentFinder.getArchiveFile();
262	                    } else if(file.isArchive()) {
263	                        archiveToExtract = new FMArchive(file.getFile());
264	                    }
265	                    if(archiveToExtract != null) {
266	                        if (new PrefUtils<Boolean>(USE_CONTEXT_FOR_OPS).getValue()) {
267	                            addFileToOpContext(EXTRACT, archiveToExtract);
268	                            if (new PrefUtils<Boolean>(USE_CONTEXT_FOR_OPS_TOAST).getValue()) {
269	                                Toast.makeText(this, getString(R.string.file_added_to_context) + archiveToExtract.getName(), LENGTH_SHORT).show();
270	                            }
271	
272	                            PrefUtils<Boolean> alwaysExtractInCurrentPref = new PrefUtils<>(ALWAYS_EXTRACT_IN_CURRENT_DIR);
273	                            if(alwaysExtractInCurrentPref.getValue()) {
274	                                finishFileOperation();
275	                            } else {
276	                                new AlertDialog.Builder(this)
277	                                        .setView(R.layout.layout_extract_now_prompt)
278	                                        .setPositiveButton(R.string.yes, (dialog, which) -> finishFileOperation())
279	                                        .setNeutralButton(R.string.yes_and_remember, (dialog, which) -> alwaysExtractInCurrentPref.setValue(true))
280	                                        .setNegativeButton(R.string.no, (dialog, which) -> Log.d(TAG, "noop")).create().show();
281	                            }
282	                        } else {
283	                            final FMFile finalArchiveToExtract = archiveToExtract; // 👀
284	                            AlertDialog alertDialog = arrayAdapter.getGenericFileOpDialog(
285	                                    R.string.extract,
286	                                    R.string.op_destination,
287	                                    R.drawable.ic_present_to_all_black_24dp,
288	                                    R.layout.layout_path_prompt,
289	                                    (d) -> new ArchiveExtractionTask(this, ((EditText) d.findViewById(R.id.destinationPath)).getText().toString(), finalArchiveToExtract, success -> {
290	                                        clearFileOpCache();
291	                                        reloadCurrentDirectory();
292	                                        if(!success) {
293	                                            Toast.makeText(FileActivity.this, R.string.unable_to_extract_archive, Toast.LENGTH_LONG).show();
294	                                        }
295	                                    }).execute(),
296	                                    (d) -> Log.d(TAG, "Cancelled."));
297	                            alertDialog.setOnShowListener(d -> arrayAdapter.presetPathForDialog(finalArchiveToExtract, alertDialog));
298	                            alertDialog.show();
299	                        }
300	                    } else {
301	                        Toast.makeText(this, R.string.unable_to_recognize_archive_format, Toast.LENGTH_LONG).show();
302	                    }
303	                    reloadCurrentDirectory();
304	                }
305	            }
306	        }
307	    }
