/**
 * Index of the first visible item of the {@link #fileListView} before a reload.
 *
 * @see #saveScrollPosition()
 * @see #restoreScrollPosition()
 */
private int scrollPosition = 0;

/**
 * Pixel offset of the first visible item of the {@link #fileListView} before a reload.
 *
 * @see #saveScrollPosition()
 * @see #restoreScrollPosition()
 */
private int scrollOffset = 0;

/**
 * True if there is a saved scroll position that needs to be restored after the next load.
 *
 * @see #saveScrollPosition()
 * @see #restoreScrollPosition()
 */
private boolean scrollPositionSaved = false;

/**
 * F5
 * <p>
 * Keeps the current scroll position since the content of the list doesn't change (much)
 * when simply reloading the directory that is already displayed.
 */
public void reloadCurrentDirectory() {
    saveScrollPosition();
    loadPath(currentDirectory);
}

/**
 * Saves the current scroll position of the {@link #fileListView} so it can be restored
 * after the list has been (re-)populated.
 *
 * @see #restoreScrollPosition()
 */
private void saveScrollPosition() {
    if (fileListView != null) {
        scrollPosition = fileListView.getFirstVisiblePosition();
        View firstVisibleItem = fileListView.getChildAt(0);
        scrollOffset = (firstVisibleItem == null) ? 0 : (firstVisibleItem.getTop() - fileListView.getPaddingTop());
        scrollPositionSaved = true;
    }
}

/**
 * Restores a previously saved scroll position of the {@link #fileListView}.
 * Does nothing if no scroll position has been saved.
 *
 * @see #saveScrollPosition()
 */
private void restoreScrollPosition() {
    if (scrollPositionSaved) {
        scrollPositionSaved = false; // only restore once per saved position
        if (fileListView != null) {
            final int position = scrollPosition;
            final int offset = scrollOffset;
            fileListView.setSelectionFromTop(position, offset);
            // the adapter has just been set, so the list may not be laid out yet
            fileListView.post(() -> fileListView.setSelectionFromTop(position, offset));
        }
    }
}

